import {applyMotion,animateView,celebrate,runeGraphic} from './motion.js';
import {curriculum,weeks,dungeons,bosses,shop,resources,shadows} from './curriculum.js';
import {initial,today,addDate,dayNumber,totals,templates,completeMission,completeHabit,reconcile,fatigue,completeRecovery,missionDone,clearRaid,buy,validateImport,threshold} from './engine.js';
const KEY='analyst-system-v1';const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageOK=true,state;
try{const raw=localStorage.getItem(KEY);state=raw?validateImport(JSON.parse(raw)):initial()}catch(e){state=initial();storageOK=false;}
let page=location.hash.slice(1)||'status',filter=0,search='',guideTab='overview',selectedDay=Math.min(90,Math.max(1,dayNumber(state.player.start))),toastTimer;
let focus={started:0,seconds:0,running:false};
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true}catch{storageOK=false;toast('Browser storage is unavailable. Export a backup before closing.')}}
reconcile(state);save();
function notifyAndRender(message){save();render();toast(message)}
function toast(message){if(/quest cleared|XP|Raid cleared|Shadow extracted/i.test(message))celebrate(/raid/i.test(message)?'raid':'quest');const t=$('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4200)}
function dateLabel(d){return new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short'})}
function actualDay(){return dayNumber(state.player.start)}
function currentDay(){return Math.min(90,Math.max(1,actualDay()))}
function completedCount(start=1,end=90){return curriculum.filter(d=>d.day>=start&&d.day<=end&&missionDone(state,d.day)).length}
function route(name){if(!['status','quests','dungeons','arsenal','shadows','guide','settings'].includes(name))name='status';page=name;location.hash=name;render();window.scrollTo({top:0,behavior:'smooth'})}
const pageNames={status:'Status window',quests:'Quest log',dungeons:'Dungeons & raids',arsenal:'System shop',shadows:'Shadow army',guide:'System guide',settings:'Settings'};
const icons={status:'▦',quests:'☷',dungeons:'◇',arsenal:'▱',shadows:'♜',guide:'⌘',settings:'⚙'};
function shell(body){const t=totals(state),day=currentDay();return `<div class="layout"><aside class="sidebar"><div class="brand"><span class="brandmark">S</span>SYSTEM</div><div class="brand-sub">YOUR NEXT EVOLUTION</div><p class="nav-label">COMMAND CENTER</p><nav class="nav" aria-label="Main navigation">${Object.entries(pageNames).map(([id,name])=>`<button data-route="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icons[id]}</span><span>${name}</span>${id==='quests'?`<span class="count">90</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="local-note"><b>Built one day at a time.</b>Your progress stays in this browser. Export a backup to carry it with you.</div><div class="player-mini"><div class="avatar-mini">${esc(state.player.name.slice(0,1).toUpperCase())}</div><div><div style="font-size:12px">${esc(state.player.name)}</div><div class="muted" style="font-size:10px;margin-top:4px">Level ${t.level} · ${t.rank}-Rank Hunter</div></div><button class="btn ghost small" data-route="settings" style="margin-left:auto;padding:6px" aria-label="Player settings">↗</button></div></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb"><span>SYSTEM</span><span>/</span><span>${pageNames[page]||pageNames.status}</span></div><div class="top-actions"><span class="online"><i class="dot"></i>SYSTEM ONLINE</span><span class="muted">${dateLabel(today())} · IST</span><span class="gold-pill">✦ <b>${t.gold.toLocaleString()}</b> <span style="font-size:9px">GOLD</span></span></div></header><main id="main" class="content" tabindex="-1">${body}<footer class="footer"><span>SYSTEM / BUSINESS ANALYST ASCENSION · 90 DAYS, ONE DIRECTION.</span><span>Browser-local progress · Midnight checks in IST · <a href="#guide">System guide ↗</a></span></footer></main></div></div>`}
function greeting(title,sub,eyebrow='YOUR PERSONAL PROGRESSION SYSTEM',action=''){return `<div class="greeting"><div><div class="eyebrow accent">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${action||`<div class="day-tag"><span class="muted">THE JOURNEY</span><strong>${String(currentDay()).padStart(2,'0')}<span class="muted" style="font-size:12px"> / 90</span></strong></div>`}</div>`}
function hunterArt(){return `<svg class="hunter-art" viewBox="0 0 230 280" role="img" aria-label="Geometric hunter silhouette inside a glowing gateway"><defs><linearGradient id="cloak" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#809864"/><stop offset=".5" stop-color="#354830"/><stop offset="1" stop-color="#19281e"/></linearGradient><linearGradient id="blade"><stop stop-color="#c5f277"/><stop offset="1" stop-color="#7baf5c" stop-opacity=".1"/></linearGradient><radialGradient id="aura"><stop stop-color="#d3ef8c" stop-opacity=".2"/><stop offset="1" stop-color="#c5f277" stop-opacity="0"/></radialGradient></defs><ellipse cx="130" cy="155" rx="100" ry="120" fill="url(#aura)"/><path d="M48 247V75l80-42 74 42v172" fill="none" stroke="#a5c67b" stroke-opacity=".4"/><path d="M60 246V85l68-38 61 38v162" fill="none" stroke="#9cbb73" stroke-opacity=".17"/><path d="M37 224h179M36 207h180" stroke="#99b47b" stroke-opacity=".07"/><ellipse cx="132" cy="256" rx="68" ry="8" fill="#0c140e" opacity=".5"/><path d="M112 80l15-14 18 11 7 29-16 17-23-13z" fill="#28352b" stroke="#697e51" stroke-width="1"/><path d="M111 83l20-15 18 13-24-4z" fill="#93ad6c"/><path d="M117 97l12 3 13-6-7 17-12-2z" fill="#13241c"/><path d="M122 100l7 1 6-3" stroke="#d8ff9a" stroke-width="2"/><path d="M114 113l-27 15-16 69 22 12 6-45-8 90 29-9 14-15 11 23 44 1-19-71-12-53-24-16z" fill="url(#cloak)" stroke="#708354" stroke-width=".6"/><path d="M106 121l20 34-22 90 29-20 20 26-13-96 15-28-22 8z" fill="#192c23"/><path d="M125 134l8 22 15-24-12 11z" fill="#a2be73" opacity=".75"/><path d="M98 143l-13 42-8 13-9-7 14-49zM156 138l13 47 21 19-8 10-28-24-11-41z" fill="#405638"/><path d="M103 246l-5 18 22 1 5-31M140 234l5 28h25l-12-17" fill="#1a2820" stroke="#697e51" stroke-width="1"/><path d="M183 195l8 7-51 66 39-67z" fill="url(#blade)"/><path d="M175 204l13 9M194 188l-7 11" stroke="#c0e385" stroke-width="2"/><path d="M83 132l25-9M158 130l-16 6" stroke="#b2cd83" stroke-opacity=".5"/><circle cx="45" cy="125" r="2" fill="#bde88a"/><circle cx="202" cy="160" r="2" fill="#bde88a"/><path d="M183 57l3-7 3 7-3 7zM57 187l3-6 3 6-3 6z" fill="#bde88a" opacity=".5"/></svg>`}
function radar(stats){const keys=['INT','PER','VIT','AGI','STR'],pts=(scale)=>keys.map((k,i)=>{const a=(-90+i*72)*Math.PI/180;const r=scale*(typeof scale==='number'?1:1);return [100+Math.cos(a)*r,91+Math.sin(a)*r]});const p=keys.map((k,i)=>{const a=(-90+i*72)*Math.PI/180,r=32+34*Math.min(1,(stats[k]-10)/100);return `${100+Math.cos(a)*r},${91+Math.sin(a)*r}`}).join(' ');return `<svg class="radar" viewBox="0 0 200 180" role="img" aria-label="Radar of INT ${stats.INT}, PER ${stats.PER}, VIT ${stats.VIT}, AGI ${stats.AGI}, STR ${stats.STR}">${[22,44,66].map(r=>`<polygon points="${pts(r).map(x=>x.join(',')).join(' ')}" fill="none" stroke="#3b4250" stroke-width=".7"/>`).join('')}${pts(66).map(([x,y])=>`<line x1="100" y1="91" x2="${x}" y2="${y}" stroke="#333c47" stroke-width=".7"/>`).join('')}<polygon points="${p}" fill="#c5f27722" stroke="#bedf88" stroke-width="1.3"/>${keys.map((k,i)=>{const a=(-90+i*72)*Math.PI/180;return `<text x="${100+Math.cos(a)*83}" y="${94+Math.sin(a)*81}" font-size="9" fill="#8c98a6" text-anchor="middle" font-family="Arial">${k}</text>`}).join('')}</svg>`}
function journey(){return `<section class="card journey"><div class="card-heading"><h2>Your 90-day ascension</h2><span class="muted">${completedCount()} / 90 missions cleared</span></div><div class="journey-grid">${curriculum.map(d=>`<button class="day-cell ${missionDone(state,d.day)?'complete':''} ${d.boss?'boss':''} ${d.day===currentDay()?'current':''}" data-day="${d.day}" aria-label="Day ${d.day}: ${esc(d.title)}, ${missionDone(state,d.day)?'complete':'incomplete'}" title="Day ${d.day} · ${esc(d.title)}">${d.boss?'◇':d.day}</button>`).join('')}</div><div class="legend"><span>ONE SMALL CLEAR, EVERY DAY.</span><div class="legend-items"><span><i class="legend-dot"></i>Uncleared</span><span><i class="legend-dot" style="background:#658748"></i>Cleared</span><span><i class="legend-dot" style="border:1px solid var(--amber)"></i>Boss raid</span></div></div></section>`}
function statusPage(){const t=totals(state),f=fatigue(state),day=currentDay(),d=curriculum[day-1],log=state.days[today()]||{},m=state.missions[day]||{},count=(log.habits||[]).length+!!m.study+!!m.speak;return `${greeting(`Welcome back, ${esc(state.player.name)}.`,`Build useful skills, create real artifacts and advance one quest at a time.`)}${!storageOK?'<div class="banner"><p>Storage is unavailable. Export a backup before leaving.</p><button class="btn small" data-action="export">Export backup</button></div>':''}<div class="hero-grid"><section class="card status-card"><div class="status-inner"><div class="eyebrow accent" style="font-size:9px">PLAYER STATUS <span style="margin-left:8px;color:#7d8d73">// ACTIVE</span></div><div class="status-heading"><h2>${esc(state.player.name)}</h2><span class="rank">${t.rank}</span></div><div class="status-class">${esc(state.player.target)}</div><div class="status-metrics"><div><strong>${String(t.level).padStart(2,'0')}</strong><div class="label">CURRENT LEVEL</div></div><div><strong>${t.xp.toLocaleString()}</strong><div class="label">TOTAL EXPERIENCE</div></div><div><strong>${completedCount()}</strong><div class="label">MISSIONS CLEARED</div></div></div></div><div class="status-progress"><div class="bar-label"><span>LEVEL ${t.level} → ${t.level+1}</span><span>${t.current} / ${t.required} XP</span></div><div class="bar"><i style="width:${t.percent}%"></i></div></div>${hunterArt()}</section><section class="card stats-card"><div class="card-heading"><h2>Core attributes</h2><span class="muted">BASE 10 + EARNED</span></div><div class="stats-layout">${radar(t.stats)}<div class="stat-list">${[['STR','Strength','✧'],['AGI','Agility','↗'],['VIT','Vitality','♡'],['INT','Intelligence','⌘'],['PER','Perception','◎']].map(([k,n,i])=>`<div class="stat-row"><span class="stat-icon">${i}</span><span class="muted">${k}</span><span>${n}</span><strong>${t.stats[k]}</strong></div>`).join('')}</div></div><div class="stats-foot"><div><div class="meter-head"><span>♡ HP</span><span>${f.hp} / 100</span></div><div class="bar"><i style="width:${f.hp}%;background:var(--cyan)"></i></div></div><div><div class="meter-head"><span>◷ FATIGUE</span><span>${f.fatigue} / 80</span></div><div class="bar"><i style="width:${f.fatigue/80*100}%;background:var(--purple)"></i></div></div></div></section></div><div class="section-title"><h2>Your path to ascension</h2><button class="btn ghost small" data-route="quests">Explore roadmap ↗</button></div><div class="phase-grid">${[['01','The foundation','Discovery · requirements · Agile',1,30],['02','The analyst’s toolkit','Excel · SQL · Power BI · integrations',31,60],['03','The final ascension','UAT · change · capstone · interviews',61,90]].map(([n,name,sub,a,b])=>`<button class="phase ${day>=a&&day<=b?'current':''}" data-phase="${n}"><div class="phase-top"><span>CHAPTER ${n} / DAYS ${a}–${b}</span><span class="phase-icon">${day>=a&&day<=b?'↗':'◇'}</span></div><strong>${name}</strong><p>${sub}</p><div class="bar"><i style="width:${completedCount(a,b)/30*100}%"></i></div></button>`).join('')}</div><div class="work-grid"><section class="card daily-card"><div class="card-heading"><h2>The daily preparation</h2><span class="tag">${count} / 7 COMPLETE</span></div><div class="mini-sub">Small commitments. Compounding returns.</div>${[{id:'study',name:'Complete today’s BA mission',detail:`${state.player.minutes} minutes · ${d.technique}`,xp:80,done:!!m.study},{id:'speak',name:'Train your stakeholder voice',detail:'10-minute drill · record, listen, improve',xp:20,done:!!m.speak},...templates.map(x=>({...x,done:(log.habits||[]).includes(x.id)}))].map(q=>`<div class="quest-row"><button class="quest-check ${q.done?'done':''}" ${q.done?'disabled':''} data-${['study','speak'].includes(q.id)?'day="'+day+'"':'habit="'+q.id+'"'} aria-label="${q.done?'Completed: ':'Complete: '}${esc(q.name)}">${q.done?'✓':''}</button><div class="quest-copy"><strong>${q.name}</strong><span>${esc(q.detail)}</span></div><span class="quest-xp">+${q.xp} XP</span></div>`).join('')}<div class="quest-footer"><span>${log.exempt?'REST DAY · PENALTIES PAUSED':'RESETS AT MIDNIGHT · ASIA/KOLKATA'}</span><button data-action="rest-day" class="btn ghost small">${log.exempt?'Resume day':'Take a rest day'}</button></div></section><section class="card mission-card"><div class="card-heading"><h2>Today’s main quest</h2><span class="muted">DAY ${String(day).padStart(2,'0')}</span></div><div class="mission-top"><span class="tag">${weeks[d.week-1][2]}-RANK MISSION</span><span class="pill">WEEK ${d.week}</span></div><h3>${d.title}</h3><p>${d.task}</p><div class="tool-chips">${d.tools.split(',').map(x=>`<span class="chip">${esc(x.trim())}</span>`).join('')}</div><p style="font-size:10px;margin-bottom:0">CLEAR CONDITION</p><p style="margin-top:5px">${d.acceptance}</p><div class="mission-bottom"><span class="reward">✦ 100 XP <span class="muted">+ 25 GOLD</span></span><button class="btn" data-day="${day}">${missionDone(state,day)?'Review mission':'Enter mission'} ↗</button></div></section></div>${state.penalty&&!state.penalty.done?`<div class="banner"><p><b>Recovery quest assigned.</b> ${state.penalty.missedDates.length} day(s) had unfinished tasks. Spend 10 minutes reviewing the blocker and choosing a smaller next step.</p><button class="btn secondary small" data-action="recovery">Open recovery quest ↗</button></div>`:''}${journey()}<div class="banner" style="border-color:#363f4b;background:#1a2028"><p style="color:var(--muted)"><b style="color:var(--text)">Your next evolution starts here.</b> Build a portfolio through requirements, process design, data analysis and testing.</p><button class="btn ghost small" data-route="guide">How the system works ↗</button></div>`}
function questsPage(){const list=curriculum.filter(d=>(!filter||d.phase===filter)&&(!search||`${d.title} ${d.tools} ${d.technique}`.toLowerCase().includes(search.toLowerCase())));return `${greeting('The quest log.','90 distinct assignments. Learn, build, explain. Every clear leaves evidence.','YOUR TRAINING ARC',`<button class="btn secondary" data-action="csv">Download all 90 days ↓</button>`)}<div class="card card-pad"><div class="card-heading"><h2>Your daily training rhythm</h2><span class="tag">${state.player.minutes} MIN / DAY</span></div><p class="muted small">${Math.round(state.player.minutes*2/9)} min learn a technique → ${Math.round(state.player.minutes*5/9)} min build an artifact → ${Math.round(state.player.minutes/9)} min speak it aloud → ${state.player.minutes-Math.round(state.player.minutes*2/9)-Math.round(state.player.minutes*5/9)-Math.round(state.player.minutes/9)} min review and log evidence. Days 7, 14 and other weekly reviews are lighter consolidation sessions. The three boss reviews are on Days 30, 60 and 90.</p></div><div class="tabs">${[['All 90 days',0],['01 · Foundation',1],['02 · Tools & evidence',2],['03 · Portfolio & impact',3]].map(([n,v])=>`<button class="tab ${filter===v?'active':''}" data-filter="${v}">${n}</button>`).join('')}</div><div class="field" style="margin-top:0"><label for="quest-search">Find a skill, tool or mission</label><input id="quest-search" placeholder="Try SQL, BPMN, stakeholder, UAT…" value="${esc(search)}"></div><div class="roadmap-list" id="roadmap-list">${list.map(d=>`<button class="day-row" data-day="${d.day}"><span class="day-num">${String(d.day).padStart(2,'0')}</span><span><h3 ${d.boss?'class="milestone"':''}>${d.title}</h3><p>${esc(d.tools)} · ${esc(d.technique)}</p></span><span class="end">${dateLabel(addDate(state.player.start,d.day-1))}<br>${d.day>actualDay()?'Preview available':missionDone(state,d.day)?'CLEARED':'100 XP · 25 GOLD'}</span><span style="color:${missionDone(state,d.day)?'var(--lime)':'var(--muted)'}">${missionDone(state,d.day)?'✓':'↗'}</span></button>`).join('')||'<p class="empty">No missions match that search.</p>'}</div>`}
function dungeonsPage(){return `${greeting('Enter the dungeon.','Fourteen gates. Three bosses. Build the evidence to earn your ascension.','PROJECTS & MILESTONES')}${dungeonMap()}<div class="section-title"><h2>Boss raids</h2><span class="muted">DAY 30 / 60 / 90</span></div><div class="grid-three">${bosses.map(b=>raidCard(b,true)).join('')}</div><div class="section-title"><h2>Ranked dungeons</h2><span class="muted">14 PROJECT GATES · E → S</span></div><div class="grid-three">${dungeons.map(d=>raidCard(d,false)).join('')}</div>`}
function raidCard(r,boss){const start=r.start||r.day-29,end=r.end||r.day,done=completedCount(start,end),total=end-start+1,cleared=state.raids[r.id];return `<section class="card raid-card"><div class="raid-head"><span class="eyebrow ${boss?'':'muted'}" style="color:${boss?'var(--amber)':''}">${boss?'BOSS RAID':'DUNGEON '+String(dungeons.indexOf(r)+1).padStart(2,'0')}</span><span class="rank-badge">${boss?'DAY '+r.day:r.rank+'-RANK'}</span></div><div class="raid-visual">${runeGraphic(boss?r.day:dungeons.indexOf(r),boss)}</div><h3>${r.name}</h3><p>${boss?r.artifact:r.subtitle}</p><div class="bottom"><div class="bar"><i style="width:${done/total*100}%;background:${boss?'var(--amber)':'var(--lime)'}"></i></div><div class="bar-label"><span>DAYS ${start}–${end}</span><span>${done} / ${total} MISSIONS</span></div><div class="loot">+${r.xp} XP · +${r.gold} GOLD${r.shadow?`<br><span style="color:var(--purple);display:block;margin-top:7px">♜ ${r.shadow}</span>`:''}</div><button class="btn ${cleared?'ghost':'secondary'} small" data-raid="${r.id}">${cleared?'✓ Review clear':'Review & clear raid'} ↗</button></div></section>`}
function arsenalPage(){return `${greeting('Earn your downtime.','A simple reward loop. Gold is imaginary; real purchases still follow your real budget.','THE SYSTEM SHOP',`<span class="tag" style="font-size:14px;padding:11px">✦ ${totals(state).gold} GOLD</span>`)}<div class="grid-three">${shop.map(i=>`<section class="card raid-card"><div class="shop-icon">${i.icon}</div><h3 style="margin-top:8px">${i.name}</h3><p>${i.desc}</p><div class="bottom"><div class="loot" style="color:var(--amber)">${i.cost} GOLD</div><button class="btn secondary small" data-buy="${i.id}" ${totals(state).gold<i.cost?'disabled':''}>Purchase reward ↗</button></div></section>`).join('')}</div><div class="banner"><p>Full daily completion earns 46 gold. A 60-gold reward takes about two days; bigger rewards take longer. Quest rewards are paid once. No gold comes from repeating recovery tasks.</p></div><div class="section-title"><h2>Your inventory</h2><span class="muted">${state.inventory.filter(x=>!x.used).length} AVAILABLE</span></div><section class="card">${state.inventory.length?state.inventory.slice().reverse().map(i=>`<div class="inventory-row"><span style="color:var(--amber)">✦</span><div><h3 style="font-size:12px">${esc(i.name)}</h3><p class="small muted">${i.cost} gold · ${dateLabel(i.purchasedAt)}</p></div><button class="btn ${i.used?'ghost':'secondary'} small" data-redeem="${esc(i.id)}" ${i.used?'disabled':''}>${i.used?'Redeemed ✓':'Use reward'}</button></div>`).join(''):'<p class="empty">Your inventory is waiting. Clear a quest and earn your first reward.</p>'}</section>`}
function shadowsPage(){return `${greeting('Your work, working for you.','Extract reusable templates from cleared dungeons. Activate them as your personal workflow library.','THE SHADOW ARMY')}<div class="banner" style="margin:0 0 20px"><p>Shadows are downloadable templates and checklists. Activation pins them to your army; it does not connect accounts or run external automations.</p></div><div class="grid-three">${dungeons.map((d,i)=>{const unlocked=!!state.raids[d.id],active=state.activeShadows.includes(d.id);return `<section class="card shadow-card ${unlocked?'':'locked'}"><div class="shadow-symbol">${runeGraphic(i,false)}</div><span class="tag" style="color:var(--purple);border-color:#a793d34d">${unlocked?(active?'ACTIVE SHADOW':'EXTRACTION AVAILABLE'):'LOCKED · DUNGEON '+(i+1)}</span><h3>${d.shadow}</h3><p>${unlocked?'A reusable starting point. Adapt it to each problem.':'Clear '+d.name+' to extract this template.'}</p>${unlocked?`<button class="btn secondary small" data-shadow="${d.id}">${active?'Deactivate':'Extract & activate'} ♜</button> <button class="btn ghost small" data-download-shadow="${d.id}">Download ↓</button>`:'<button class="btn ghost small" data-route="dungeons">View dungeon ↗</button>'}</section>`}).join('')}</div>`}
function dungeonMap(){return `<section class="card dungeon-constellation"><div class="card-heading"><div><span class="eyebrow accent">THE GATE NETWORK</span><h2 style="margin-top:8px">Your 14-dungeon campaign</h2></div><span class="tag">${dungeons.filter(d=>state.raids[d.id]).length} / 14 CLEARED</span></div><div class="dungeon-map">${dungeons.map((d,i)=>`<button class="map-gate ${state.raids[d.id]?'cleared':''}" data-raid="${d.id}" aria-label="Dungeon ${i+1}: ${esc(d.name)}, ${d.rank}-Rank, days ${d.start} to ${d.end}"><span class="gate-orb">${runeGraphic(i)}<span class="gate-number">${String(i+1).padStart(2,'0')}</span></span><b>${d.rank}-RANK</b><small>DAYS ${d.start}–${d.end}</small></button>`).join('')}</div><p class="small muted">Select a gate to inspect its clear conditions. Each completed dungeon adds a new template to your Shadow Army.</p></section>`}
const schemaRows=[
 ['Player','id (ID), name (Text), start (Date), minutes (Number), target (Select), events (Relation), Total EXP / Gold (Rollup), Level / Rank / Stats / HP (Formula)','1 → many RewardEvent, DailyLog, QuestInstance, RaidClear, Purchase'],
 ['CurriculumDay','day (Number, PK), week / phase (Select), title / task / acceptance / drill (Text), tools (Multi-select), resource (URL), boss (Checkbox)','1 → many QuestInstance; many → Dungeon through day range'],
 ['QuestTemplate','id (ID), name / detail (Text), recurrence (Select: daily), xp / gold (Number), stat (Select), stat points (Number)','1 → many QuestInstance; five lifestyle templates plus study/speak types'],
 ['QuestInstance','id (ID), player / template / day (Relation), scheduled_date (Date), completed_date (Date), evidence (Text), status (Select)','Stored in missions[day] and days[date].habits; one completion → one RewardEvent'],
 ['RewardEvent','id (ID, unique), source (Text / source relation), date (Date), xp / gold (Number), stats (JSON numbers), createdAt (Datetime)','Many → Player; immutable award/purchase ledger; XP and signed Gold roll up'],
 ['DailyLog','player (Relation), date (Date), habits (Relation set), minutes (Number), exempt / recovery (Checkbox), fatigue / HP (Formula)','Composite key player + date; closure uses this log'],
 ['DayClosure','date (Date, unique per player), missed (Number), closedAt / due (Date)','Many → Player; creates/merges RecoveryTask; prevents repeated midnight processing'],
 ['RecoveryTask','id (ID), due (Date), missedDates (Date array), note (Text), done (Checkbox), completedAt (Date)','One active per player; no XP or gold reward; adds recovery flag to DailyLog'],
 ['Dungeon / Boss','id (ID), name (Text), rank (Select), start/end or day (Number), xp/gold (Number), shadow (Relation)','Many required CurriculumDays → one raid; one clear per Player'],
 ['RaidClear','player / raid (Relation), date (Date), note (Text), checks (Checkbox array)','Unique player + raid; creates RewardEvent; dungeon clear unlocks Shadow'],
 ['ShopItem','id (ID), name / desc (Text), cost (Number), icon (Text)','1 → many Purchase records; four fixed prices'],
 ['Purchase / Inventory','id (ID), itemId (Relation), name (Text snapshot), cost (Number snapshot), purchasedAt (Date), used (Checkbox)','Many → Player and ShopItem; matching signed negative Gold RewardEvent'],
 ['Shadow','id (same as dungeon, ID), name / template (Text), unlocked (Rollup from clear), active (Checkbox)','One per Dungeon; active IDs in activeShadows; templates in curriculum.js'],
 ['RecoveryMissedDay','task_id / player_id (Relation), missed_date (Date); composite unique task + date','SQL bridge for RecoveryTask.missedDates; references DayClosure'],
 ['RaidRequirement','raid_id / curriculum_day (Relation); composite unique raid + day','SQL bridge for required training days; app derives it from start/end ranges'],
 ['PlayerShadow','player_id / shadow_id (Relation), active (Checkbox); composite unique player + shadow','SQL bridge for a player’s extracted shadows; app stores active IDs']
];
const formulas=`// Copy-pasteable JavaScript; pass the save file's events object.
function playerTotals(events) {
  const rows = Object.values(events);
  const xp = rows.reduce((sum, e) => sum + e.xp, 0);
  const gold = rows.reduce((sum, e) => sum + e.gold, 0);
  const level = Math.floor((Math.sqrt(9 + 0.08 * xp) - 1) / 2);
  const threshold = L => 50 * (L - 1) * (L + 2);
  const rank = level >= 21 ? 'S' : level >= 17 ? 'A' :
    level >= 13 ? 'B' : level >= 9 ? 'C' : level >= 5 ? 'D' : 'E';
  const stats = Object.fromEntries(['STR','AGI','VIT','INT','PER']
    .map(k => [k, 10 + rows.reduce((sum,e) => sum + (e.stats?.[k] || 0), 0)]));
  return {xp, gold, level, rank, stats,
    current: xp - threshold(level),
    required: 100 * (level + 1),
    remaining: threshold(level + 1) - xp};
}
function dayFatigue(previous, missed, minutes, rest, recovery, exempt) {
  if (exempt) return previous;
  const overwork = 4 * Math.ceil(Math.max(0, minutes - 180) / 30);
  const recovered = (rest ? 12 : 0) + (recovery ? 8 : 0);
  return Math.min(80, Math.max(0,
    previous + Math.min(12, 3 * missed) + overwork - recovered));
}
// Process dates chronologically; HP = 100 - fatigue.
`;
const notionFormulas=`/* Notion Formula 2.0 — Player database */\n/* Total EXP: Rollup Reward Events → XP → Sum */\n/* STR Earned etc.: Rollup Reward Events → STR etc. → Sum */\n\n/* Level */\nfloor((sqrt(9 + 0.08 * prop("Total EXP")) - 1) / 2)\n\n/* Rank */\nifs(prop("Level") >= 21, "S", prop("Level") >= 17, "A", prop("Level") >= 13, "B", prop("Level") >= 9, "C", prop("Level") >= 5, "D", "E")\n\n/* EXP to Next Level */\n50 * prop("Level") * (prop("Level") + 3) - prop("Total EXP")\n\n/* Current Level EXP */\nprop("Total EXP") - 50 * (prop("Level") - 1) * (prop("Level") + 2)\n\n/* STR Total */\n10 + prop("STR Earned")\n\n/* AGI Total */\n10 + prop("AGI Earned")\n\n/* VIT Total */\n10 + prop("VIT Earned")\n\n/* INT Total */\n10 + prop("INT Earned")\n\n/* PER Total */\n10 + prop("PER Earned")\n\n/* Gold: Rollup Reward Events → Gold Delta → Sum */`;
function guidePage(){return `${greeting('Understand your system.','The architecture, exact formulas and build sequence behind your ascension.','THE OPERATING MANUAL',`<a class="btn secondary" href="./SYSTEM_GUIDE.md" download>Download guide ↓</a>`)}<div class="tabs">${[['overview','The blueprint'],['schema','Object schema'],['formulas','Exact formulas'],['setup','30-minute setup'],['resources','Tools & resources']].map(([id,n])=>`<button class="tab ${guideTab===id?'active':''}" data-guide="${id}">${n}</button>`).join('')}</div>${guideTab==='overview'?`<div class="guide-grid"><section class="card guide-card"><h2>The status window wireframe</h2><div class="wire"><div class="wide">HEADER · Player / day / gold / settings</div><div>PLAYER STATUS<br>Level · rank · total XP · XP bar</div><div>CORE ATTRIBUTES<br>Radar · STR / AGI / VIT / INT / PER<br>HP + fatigue</div><div class="wide">THREE CHAPTERS · Foundation → Toolkit → Ascension</div><div>DAILY PREPARATION<br>7 quests · rewards · rest-day control</div><div>MAIN MISSION<br>Technique · task · clear condition<br>Evidence + speaking drill</div><div class="wide">90-DAY MAP · Every day selectable · 3 boss gates</div><div class="wide">RECOVERY QUEST · Review blocker → smaller next step</div></div><p>The left sidebar opens quests, dungeons, shop, shadows, guide and settings. On mobile, it becomes a top navigation strip.</p></section><section class="card guide-card"><h2>The rules of progression</h2><p>Start at Level 1, E-Rank, with 10 in every stat. Completing learning and speaking earns 100 XP and 25 gold daily. Five lifestyle quests add 80 XP and 21 gold. Every award has a unique ledger key.</p><p style="margin-top:14px">Weekly dungeons pay 120–550 XP; bosses pay 700, 1,000 and 1,600 XP. All 90 days plus all raids give 24,130 XP, enough for Level 21 / S-Rank. Rank is a game reward; portfolio review is the skill check.</p><p style="margin-top:14px">Rest days exempt that date from penalties. At midnight IST, unfinished required quests add up to 12 fatigue and create a 10-minute recovery review. Several missed days merge into one active task. Recovery earns no currency. HP stays between 20 and 100.</p><p style="margin-top:14px">The app checks midnight while open, and catches up when reopened. A closed static website cannot run a background job. Your saved progress is local to this browser, with JSON export/import for transfer.</p></section></div><section class="card guide-card" style="margin-top:18px"><h2>The five interconnected modules</h2><div class="table-wrap"><table class="schema"><tr><th>Module</th><th>Input → result</th><th>Control</th></tr><tr><td>Status Window</td><td>Reward events + daily logs → XP, level, rank, stats, HP, fatigue</td><td>Derived totals prevent duplicate counters</td></tr><tr><td>Daily Quests</td><td>Study / speak / habits → one-time XP, gold and stats</td><td>Unique mission/day keys; evidence required for study</td></tr><tr><td>Dungeons & Bosses</td><td>Completed training days + review → clear reward and rune</td><td>Three review checks and artifact notes</td></tr><tr><td>Shop & Inventory</td><td>Gold → purchase ledger debit → usable reward</td><td>Insufficient funds blocked; fixed pricing</td></tr><tr><td>Shadow Army</td><td>Cleared dungeon → unlocked reusable template</td><td>Activate / deactivate and download; external automation is a separate implementation</td></tr></table></div></section>`:''}${guideTab==='schema'?`<section class="card guide-card"><h2>Logical relational schema & implementation mapping</h2><p>These are the object boundaries. This version uses browser-local JSON, not a server database. Relation, Rollup, Formula and Select describe equivalent workspace properties. The downloadable SQLite schema is a reference for a future synced backend.</p><div class="table-wrap"><table class="schema"><thead><tr><th>Object</th><th>Properties · types</th><th>Relationships / local mapping</th></tr></thead><tbody>${schemaRows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div style="margin-top:18px"><a class="btn secondary" href="./schema.sql" download>Download relational SQL ↓</a></div></section>`:''}${guideTab==='formulas'?`<div class="guide-grid"><section class="card guide-card"><div class="card-heading"><h2>Website formulas</h2><button class="btn ghost small" data-copy="js">Copy</button></div><pre class="formula">${esc(formulas)}</pre><p style="margin-top:14px">The running implementation is in engine.js. Awards are immutable by key. Shop purchases have zero XP and negative gold. Daily fatigue clamps after each date.</p><a href="./engine.js" download class="btn secondary small" style="margin-top:15px">Download executable engine ↓</a></section><section class="card guide-card"><div class="card-heading"><h2>Optional Notion formulas</h2><button class="btn ghost small" data-copy="notion">Copy</button></div><pre class="formula">${esc(notionFormulas)}</pre><p style="margin-top:14px">Create the exact named properties before pasting each expression. Use five separate Number fields on Reward Events for stat rollups. Notion formulas alone do not run midnight jobs or apply a chronological fatigue ledger; those need an automation.</p></section></div><section class="card guide-card" style="margin-top:18px"><h2>Reward & economy table</h2><div class="table-wrap"><table class="schema"><tr><th>Quest</th><th>XP</th><th>Gold</th><th>Stats</th></tr><tr><td>BA mission</td><td>80</td><td>20</td><td>INT +2</td></tr><tr><td>Speaking drill</td><td>20</td><td>5</td><td>PER +1</td></tr>${templates.map(t=>`<tr><td>${t.name}</td><td>${t.xp}</td><td>${t.gold}</td><td>${t.stat} +1</td></tr>`).join('')}<tr><td>Dungeon / Boss clear</td><td>120–1,600</td><td>35–400</td><td>INT +3, PER +2</td></tr><tr><td>Recovery task</td><td>0</td><td>0</td><td>Fatigue −8 once that day</td></tr></table></div></section>`:''}${guideTab==='setup'?`<section class="card guide-card"><h2>Five steps · under 30 minutes to start</h2><ol><li><b>0–5 min: Set your character.</b> Open Settings, confirm your name, start date, daily budget and target. This ready-built website requires no coding to start.</li><li><b>5–10 min: Prepare your workspace.</b> Create a portfolio folder with Discovery, Requirements, Data, UAT and Presentations subfolders. Use Docs/Markdown, diagrams.net and Excel or LibreOffice.</li><li><b>10–15 min: Inspect your first quest.</b> Open Day 1, read the task and acceptance check. Set a focus timer. Download the 90-day CSV if you want a second view.</li><li><b>15–20 min: Choose the reward loop.</b> Read the shop prices and daily quests. Adapt movement and rest to your circumstances; mark a rest day when needed. Nothing requires buying anything.</li><li><b>20–30 min: Establish the review routine.</b> Export your first backup and book a weekly self-review in your own calendar. Clear dungeons only after reviewing evidence. Download and reuse your unlocked templates.</li></ol><p>This is a 30-minute setup for the delivered app. Recreating the complete application from scratch takes longer. For GitHub Pages hosting, publish these static files and enable Pages in repository settings; see the README.</p></section>`:''}${guideTab==='resources'?resourcesPage():''}`}
function resourcesPage(){const groups=[['Business analysis & discovery','IIBA Standard; Docs/Word/Markdown; Excel stakeholder register; diagrams.net for process maps.','iiba'],['Process & design','SIPOC, BPMN, swimlanes, as-is/to-be, gap analysis, context diagrams; Figma or paper for wireframes.','bpmn'],['Agile & requirements','Jira or a spreadsheet; Confluence or Markdown; stories, INVEST, MoSCoW, RTM, Given–When–Then.','jira'],['Delivery framework','Scrum accountabilities, events, artifacts and commitments; Kanban flow and WIP controls.','scrum'],['Excel & data quality','Power Query, XLOOKUP, IF, SUMIFS, COUNTIFS, PivotTables, validation and reconciliation.','excel'],['SQL & data modelling','SELECT, filters, NULL, joins, aggregates, CASE, CTEs, window functions, ERDs and key/cardinality checks.','sql'],['Power BI & decision reporting','Star schema, relationships, Power Query, DAX, CALCULATE, DIVIDE, filters and drill-through.','bi'],['Integration & business systems','Postman, HTTP/JSON, source-to-target mapping, validation, idempotency, retries and audit trails.','api'],['Supply chain context','Conceptual SAP S/4HANA TM/MM, Blue Yonder/TMS/WMS workflows and master-data governance. No live system access required.','sap'],['Change & automation','Power Automate sandbox or paper flow; human approval, failure queue, SOP, training, pilot and rollback.','automate']];return `<div class="toolkit">${groups.map(([name,desc,id])=>`<section class="card tool-card"><div class="eyebrow accent">LEARN → PRACTISE → EXPLAIN</div><h3>${name}</h3><p>${desc}</p><a href="${resources[id].url}" target="_blank" rel="noopener noreferrer">${resources[id].name} ↗</a></section>`).join('')}</div><section class="card guide-card" style="margin-top:18px"><h2>Practice files & tool access</h2><p>Use fictional data for the portfolio. Excel and Power BI Desktop suit a Windows machine; LibreOffice can cover much of the spreadsheet work. If Power BI is unavailable, create the decision view in Excel and document the DAX/model design separately. T-SQL learning examples differ from the included SQLite starter in date syntax. Use SAP/Blue Yonder documentation or generic diagrams; this plan does not require enterprise logins. Resource availability and paid access vary.</p><div class="tabs"><a class="btn secondary small" href="./shipments.csv" download>Synthetic shipment data ↓</a><a class="btn secondary small" href="./practice.sql" download>SQLite starter ↓</a><button class="btn secondary small" data-action="csv">90-day roadmap ↓</button></div><p>Resource list checked 24 October 2026. The daily assignments and progression rules are an original learning design, not an accredited qualification or a promise of employment.</p></section>`}
function settingsPage(){return `${greeting('Tune the system.','Make the rhythm fit your life. Small, consistent progress wins.','PLAYER SETTINGS')}<div class="guide-grid"><section class="card guide-card"><h2>Character & learning preferences</h2><form id="settings-form" class="settings-form"><div class="field"><label for="player-name">Player name</label><input id="player-name" name="name" value="${esc(state.player.name)}" maxlength="40" required></div><div class="field"><label for="start-date">Day 1 date · IST ${Object.keys(state.events).length?'(locked after your first reward)':''}</label><input type="date" id="start-date" name="start" value="${state.player.start}" ${Object.keys(state.events).length?'disabled':''} required></div><div class="field"><label for="minutes">Daily BA learning budget · includes speaking and review</label><select id="minutes" name="minutes">${[45,60,90,120,180].map(n=>`<option value="${n}" ${state.player.minutes===n?'selected':''}>${n} minutes</option>`).join('')}</select></div><div class="field"><label for="target">Target role label</label><select id="target" name="target">${['Supply chain / IT Business Analyst','General Business Analyst','Data Business Analyst'].map(n=>`<option ${state.player.target===n?'selected':''}>${n}</option>`).join('')}</select></div><p class="small muted" style="margin-bottom:17px">The supplied curriculum prioritises supply chain / IT. The target label is editable; changing it does not regenerate assignments. A smaller daily budget means producing a smaller artifact with the same quality checks.</p><div class="field motion-setting"><label for="motion">Motion & graphics</label><select id="motion" name="motion">${[['system','Follow device preference'],['full','Full motion & animated graphics'],['reduced','Reduced motion']].map(([v,n])=>`<option value="${v}" ${(state.player.motion||'system')===v?'selected':''}>${n}</option>`).join('')}</select></div><button class="btn" type="submit">Save preferences ✓</button></form></section><section class="card guide-card"><h2>Your save file</h2><p>Progress is stored in this browser’s local storage. Clearing browser data removes it. Other devices and the GitHub copy have separate saves. Export a JSON backup, then import it on another device to transfer progress.</p><div class="tabs"><button class="btn secondary" data-action="export">Export backup ↓</button><button class="btn ghost" data-action="import">Import backup ↑</button></div><p class="notice">Import replaces this browser’s current save after confirmation. Your source code does not contain your progress.</p><h2 style="margin-top:25px">Today’s study load</h2><form id="load-form"><div class="field"><label for="study-minutes">Total study minutes today (timer + manual correction)</label><input type="number" min="0" max="720" step="1" id="study-minutes" name="load" value="${state.days[today()]?.minutes||0}"></div><button class="btn secondary small">Update study minutes</button></form><p class="small muted" style="margin-top:13px">Over 180 minutes adds 4 fatigue per started 30-minute block. The focus timer records elapsed time when you save it. Rest/recovery quests reduce fatigue.</p><button class="btn ghost small" style="margin-top:25px" data-action="reset">Reset all local progress</button></section></div>`}
function render(){if(!pageNames[page])page='status';const views={status:statusPage,quests:questsPage,dungeons:dungeonsPage,arsenal:arsenalPage,shadows:shadowsPage,guide:guidePage,settings:settingsPage};applyMotion(state.player.motion||'system');$('#app').innerHTML=shell(views[page]());animateView(totals(state).level);}
function openMission(day){selectedDay=day;const d=curriculum[day-1],m=state.missions[day]||{},future=day>actualDay(),r=resources[d.resource];$('#detail').innerHTML=`<div class="dialog-head"><div><span class="eyebrow accent">DAY ${String(day).padStart(2,'0')} · WEEK ${d.week} · ${dateLabel(addDate(state.player.start,day-1))}</span><h2>${d.title}</h2></div><button class="close" data-close aria-label="Close mission">×</button></div><div class="tool-chips">${d.tools.split(',').map(x=>`<span class="chip">${esc(x)}</span>`).join('')}<span class="chip">${esc(d.technique)}</span></div>${future?'<p class="notice">Preview mode. This quest unlocks on its scheduled date. Browse ahead, then return to today’s assignment.</p>':''}<section class="mission-section"><h3>01 / LEARN THE TECHNIQUE · ${Math.round(state.player.minutes*2/9)} MIN</h3><p>Focus on ${d.technique}. Use the resource below to understand the technique, then apply it to the task rather than trying to finish an entire course.</p><p style="margin-top:10px"><a href="${r.url}" target="_blank" rel="noopener noreferrer">${r.name} ↗</a></p></section><section class="mission-section"><h3>02 / BUILD THE EVIDENCE · ${Math.round(state.player.minutes*5/9)} MIN</h3><p>${d.task}</p><div class="field"><label for="evidence">Artifact link or notes · saved automatically in this browser</label><textarea id="evidence" data-evidence="${day}" placeholder="Paste an artifact link, describe what you built, and record a limitation…">${esc(m.evidence||'')}</textarea></div><p class="small"><b style="color:var(--text)">Acceptance check:</b> ${d.acceptance}</p><button class="btn ${m.study?'ghost':'secondary'} small" style="margin-top:16px" data-complete-study="${day}" ${m.study||future?'disabled':''}>${m.study?'✓ Evidence submitted':'Submit evidence · +80 XP / 20 Gold'}</button></section><section class="mission-section"><h3>03 / TRAIN YOUR STAKEHOLDER VOICE · ${Math.round(state.player.minutes/9)} MIN</h3><p>${d.drill}</p><p style="margin-top:9px">Start with your headline. Speak audibly, use deliberate pauses, support your point with evidence and finish with a clear ask. Record with your own voice app; no recording is uploaded here.</p><div class="field"><label for="speak-note">What improved? What will you change next time?</label><textarea id="speak-note" data-speak-note="${day}" style="min-height:70px" placeholder="Clarity, volume, pace, evidence, decision request…">${esc(m.speakNote||'')}</textarea></div><button class="btn ${m.speak?'ghost':'secondary'} small" data-complete-speak="${day}" ${m.speak||future?'disabled':''}>${m.speak?'✓ Speaking drill complete':'I practised aloud · +20 XP / 5 Gold'}</button></section><section class="mission-section"><h3>04 / REVIEW & LOG · ${state.player.minutes-Math.round(state.player.minutes*2/9)-Math.round(state.player.minutes*5/9)-Math.round(state.player.minutes/9)} MIN</h3><p>Check your output against the acceptance condition. Add one correction and one next step. Completion is self-attested; use dungeon reviews to challenge the quality.</p><div class="timer"><span class="muted small">FOCUS<br>SESSION</span><strong id="focus-display">${formatTime(elapsed())}</strong><button class="btn ghost small" data-action="timer-toggle">${focus.running?'Pause':'Start'}</button><button class="btn secondary small" data-action="timer-save">Log time</button></div></section><div class="dialog-footer"><button class="btn ghost small" data-day="${Math.max(1,day-1)}" ${day===1?'disabled':''}>← Previous</button><button class="btn secondary small" data-day="${Math.min(90,day+1)}" ${day===90?'disabled':''}>Next day →</button></div>`;if(!$('#detail').open)$('#detail').showModal();}
function openRaid(id){const r=[...dungeons,...bosses].find(x=>x.id===id),clear=state.raids[id];$('#detail').innerHTML=`<div class="dialog-head"><div><span class="eyebrow accent">RAID REVIEW · ${r.xp} XP / ${r.gold} GOLD</span><h2>${r.name}</h2></div><button class="close" data-close aria-label="Close raid">×</button></div><p class="muted small">Complete both training tasks on every required day, then review the resulting work. This is your quality gate.</p><div class="field"><label for="raid-note">Evidence links, review findings and remaining gaps</label><textarea id="raid-note" placeholder="Name the artifacts and explain how you validated them…">${esc(clear?.note||'')}</textarea></div><div class="checks">${['The required artifacts are complete and trace back to the stated business need.','I checked calculations, rules or acceptance examples and recorded limitations.','I can explain the recommendation, tradeoffs and next step aloud.'].map((x,i)=>`<label><input type="checkbox" class="raid-check" ${clear?'checked disabled':''}>${x}</label>`).join('')}</div><button class="btn" data-clear-raid="${id}" ${clear?'disabled':''}>${clear?'✓ Raid already cleared':'Clear raid & claim rewards ↗'}</button>${r.shadow?`<p class="small" style="color:var(--purple);margin-top:15px">♜ Unlocks ${r.shadow} in your Shadow Army.</p>`:''}`;if(!$('#detail').open)$('#detail').showModal()}
function openRecovery(){const p=state.penalty;if(!p||p.done)return;$('#detail').innerHTML=`<div class="dialog-head"><div><span class="eyebrow" style="color:var(--amber)">THE RECOVERY ZONE · DUE ${dateLabel(p.due)}</span><h2>Reset. Reduce. Return.</h2></div><button class="close" data-close aria-label="Close recovery">×</button></div><p class="muted small">Set aside 10 minutes. Review what blocked your quests, reduce tomorrow’s scope and prepare one small next action. Several missed days merge into this single review. You do not need to make up missed exercise or sacrifice rest.</p><div class="field"><label for="recovery-note">What got in the way? What is your smaller next step?</label><textarea id="recovery-note" data-recovery-note placeholder="The blocker was… My next realistic action is…">${esc(p.note||'')}</textarea></div><button class="btn" data-action="complete-recovery">I completed my recovery review · −8 Fatigue</button><p class="small muted" style="margin-top:15px">No XP or gold. Recovery is counted at most once per day.</p>`;if(!$('#detail').open)$('#detail').showModal()}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(){const cols=['Day','Week','Phase','Title','Tools','Technique','Practice task','Acceptance check','Speaking drill','Resource'];download('Business_Analyst_90_Day_Roadmap.csv','\uFEFF'+[cols,...curriculum.map(d=>[d.day,d.week,d.phase,d.title,d.tools,d.technique,d.task,d.acceptance,d.drill,resources[d.resource].url])].map(row=>row.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function elapsed(){return focus.seconds+(focus.running?Math.max(0,Math.floor((Date.now()-focus.started)/1000)):0)}
function formatTime(sec){return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}
document.addEventListener('input',e=>{const x=e.target;if(x.matches('[data-evidence]')){const d=x.dataset.evidence;state.missions[d]||={};state.missions[d].evidence=x.value;save()}if(x.matches('[data-speak-note]')){const d=x.dataset.speakNote;state.missions[d]||={};state.missions[d].speakNote=x.value;save()}if(x.matches('[data-recovery-note]')){state.penalty.note=x.value;save()}if(x.id==='quest-search'){const pos=x.selectionStart;search=x.value;render();$('#quest-search').focus();$('#quest-search').setSelectionRange(pos,pos)}});
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-action]');if(!b)return;try{
 if(b.hasAttribute('data-close')){$('#detail').close();return}
 if(b.dataset.route){if($('#detail').open)$('#detail').close();route(b.dataset.route);return}
 if(b.dataset.day){openMission(+b.dataset.day);return}
 if(b.dataset.phase){filter=+b.dataset.phase;route('quests');return}
 if(b.dataset.filter!==undefined){filter=+b.dataset.filter;render();return}
 if(b.dataset.guide){guideTab=b.dataset.guide;render();return}
 if(b.dataset.habit){if(completeHabit(state,b.dataset.habit))notifyAndRender('Quest cleared. Your next evolution is earned.');return}
 if(b.dataset.completeStudy){const day=+b.dataset.completeStudy;if(completeMission(state,day,'study')){save();render();openMission(day);toast('+80 XP · +20 Gold · INT +2')}return}
 if(b.dataset.completeSpeak){const day=+b.dataset.completeSpeak;if(completeMission(state,day,'speak')){save();render();openMission(day);toast('+20 XP · +5 Gold · PER +1')}return}
 if(b.dataset.raid){openRaid(b.dataset.raid);return}
 if(b.dataset.clearRaid){const r=[...dungeons,...bosses].find(r=>r.id===b.dataset.clearRaid),checks=[...document.querySelectorAll('.raid-check')].map(x=>x.checked);if(clearRaid(state,r,$('#raid-note').value,checks)){$('#detail').close();notifyAndRender(`Raid cleared. +${r.xp} XP · +${r.gold} Gold${r.shadow?' · Shadow unlocked':''}`)}return}
 if(b.dataset.buy){const item=shop.find(x=>x.id===b.dataset.buy);buy(state,item);notifyAndRender(`${item.name} added to your inventory.`);return}
 if(b.dataset.redeem){const item=state.inventory.find(x=>x.id===b.dataset.redeem);if(item&&!item.used){item.used=true;item.usedAt=today();notifyAndRender('Reward redeemed. Enjoy the time you earned.')}return}
 if(b.dataset.shadow){const id=b.dataset.shadow;if(!state.raids[id])throw Error('Clear the matching dungeon first.');const active=state.activeShadows.includes(id);state.activeShadows=active?state.activeShadows.filter(x=>x!==id):[...state.activeShadows,id];notifyAndRender(active?'Shadow deactivated.':'Shadow extracted. Your reusable workflow is ready.');return}
 if(b.dataset.downloadShadow){const d=dungeons.find(x=>x.id===b.dataset.downloadShadow);if(!state.raids[d.id])throw Error('Clear the dungeon first.');download(d.shadow.replaceAll(' ','_')+'.md',shadows[d.shadow]);return}
 if(b.dataset.copy){await navigator.clipboard.writeText(b.dataset.copy==='js'?formulas:notionFormulas);toast('Formulas copied.');return}
 switch(b.dataset.action){
 case 'csv':csv();break;
 case 'export':download(`SYSTEM_Backup_${today()}.json`,JSON.stringify(state,null,2),'application/json');toast('Backup exported. Keep it somewhere you can find it.');break;
 case 'import':$('#import-file').click();break;
 case 'rest-day':{state.days[today()]||={habits:[],minutes:0,exempt:false};state.days[today()].exempt=!state.days[today()].exempt;notifyAndRender(state.days[today()].exempt?'Rest day enabled. No missed-quest fatigue for today.':'Daily quests resumed.');break}
 case 'recovery':openRecovery();break;
 case 'complete-recovery':if(completeRecovery(state)){$('#detail').close();notifyAndRender('Recovery complete. Return with a smaller next step.')}break;
 case 'timer-toggle':if(focus.running){focus.seconds=elapsed();focus.running=false}else{focus.started=Date.now();focus.running=true}openMission(selectedDay);break;
 case 'timer-save':{const minutes=Math.floor(elapsed()/60);if(!minutes)throw Error('Let the timer run for at least one minute, or log minutes in Settings.');state.days[today()]||={habits:[],minutes:0,exempt:false};state.days[today()].minutes=Math.min(720,(state.days[today()].minutes||0)+minutes);focus={seconds:0,started:0,running:false};save();render();openMission(selectedDay);toast(`${minutes} study minutes logged.`);break}
 case 'reset':if(confirm('Delete all SYSTEM progress from this browser? Export a backup first if you want to keep it.')){state=initial();focus={seconds:0,started:0,running:false};notifyAndRender('A new journey begins.')}break;
 }
 }catch(err){toast(err.message||'That action could not be completed.')}});
document.addEventListener('submit',e=>{if(e.target.id==='settings-form'){e.preventDefault();const data=new FormData(e.target),name=String(data.get('name')).trim(),start=data.get('start')||state.player.start;if(!name)return;if(!/^\d{4}-\d{2}-\d{2}$/.test(start)){toast('Choose a valid start date.');return}state.player={name,start,minutes:+data.get('minutes'),target:String(data.get('target')),motion:String(data.get('motion')||'system')};reconcile(state);notifyAndRender('Preferences saved. Your system is ready.')}if(e.target.id==='load-form'){e.preventDefault();state.days[today()]||={habits:[],minutes:0,exempt:false};state.days[today()].minutes=Math.min(720,Math.max(0,Math.floor(+new FormData(e.target).get('load')||0)));notifyAndRender('Study load updated.')}});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5_000_000)throw Error('Backup is too large.');const next=validateImport(JSON.parse(await file.text()));if(confirm(`Replace this browser’s progress with ${next.player.name}’s backup?`)){state=next;reconcile(state);notifyAndRender('Backup restored. Welcome back.')}}catch(err){toast(err.message||'Invalid backup.')}e.target.value=''});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'status';render()});
setInterval(()=>{const display=$('#focus-display');if(display)display.textContent=formatTime(elapsed())},1000);
setInterval(()=>{if(reconcile(state)){save();render();toast('Your elapsed IST days were checked. Daily quests are ready.')}},60000);
render();
